BEGIN;
ALTER TABLE "FinanceAccount" DROP CONSTRAINT "FinanceAccount_controlType_check",DROP CONSTRAINT "FinanceAccount_control_type";
ALTER TABLE "FinanceAccount" ADD CONSTRAINT "FinanceAccount_controlType_check" CHECK("controlType" IN('NONE','CASH','RECEIVABLES','PAYABLES','CLIENT_ADVANCE','SUPPLIER_ADVANCE','FIXED_ASSET','ACCUMULATED_DEPRECIATION','INVESTMENT','LOAN_RECEIVABLE','LOAN_PAYABLE','DEFERRED_REVENUE','TAX_INPUT','TAX_OUTPUT','WITHHOLDING_RECEIVABLE','WITHHOLDING_PAYABLE','CAPITAL','DISTRIBUTION','FOUNDER_PAYABLE')),ADD CONSTRAINT "FinanceAccount_control_type" CHECK("controlType"='NONE' OR(type='ASSET' AND "controlType" IN('CASH','RECEIVABLES','SUPPLIER_ADVANCE','FIXED_ASSET','ACCUMULATED_DEPRECIATION','INVESTMENT','LOAN_RECEIVABLE','TAX_INPUT','WITHHOLDING_RECEIVABLE')) OR(type='LIABILITY' AND "controlType" IN('PAYABLES','CLIENT_ADVANCE','LOAN_PAYABLE','DEFERRED_REVENUE','TAX_OUTPUT','WITHHOLDING_PAYABLE','FOUNDER_PAYABLE')) OR(type='EQUITY' AND "controlType" IN('CAPITAL','DISTRIBUTION')));
-- Distribution is a reviewed ordinary equity debit account, not an inferred ownership calculation.
ALTER TABLE "FinanceMovement" ADD COLUMN "billId" UUID REFERENCES "FinanceBill" ON DELETE RESTRICT;
ALTER TABLE "FinanceMovement" DROP CONSTRAINT "FinanceMovement_kind_check";
ALTER TABLE "FinanceMovement" ADD CONSTRAINT "FinanceMovement_kind_check" CHECK(kind IN('TRANSFER','REVERSAL','CAPITAL_CONTRIBUTION','CAPITAL_RETURN','DISTRIBUTION','NONCASH_CAPITAL','FOUNDER_OUTLAY','FOUNDER_BILL_SETTLEMENT','FOUNDER_REIMBURSEMENT'));
DO $$ DECLARE def TEXT;BEGIN SELECT pg_get_constraintdef(oid) INTO def FROM pg_constraint WHERE conrelid='public."FinanceMovement"'::regclass AND conname='FinanceMovement_source_shape';ALTER TABLE "FinanceMovement" DROP CONSTRAINT "FinanceMovement_source_shape";EXECUTE 'ALTER TABLE public."FinanceMovement" ADD CONSTRAINT "FinanceMovement_source_shape" CHECK(('||substr(def,8,length(def)-8)||' AND(kind=''REVERSAL'' OR "billId" IS NULL)) OR(kind IN(''CAPITAL_CONTRIBUTION'',''CAPITAL_RETURN'',''DISTRIBUTION'',''NONCASH_CAPITAL'',''FOUNDER_OUTLAY'',''FOUNDER_BILL_SETTLEMENT'',''FOUNDER_REIMBURSEMENT'') AND "partyId" IS NOT NULL AND "controlAccountId" IS NOT NULL AND "reversalOfId" IS NULL))';END $$;
CREATE TABLE "FinanceFundingEvent"(id UUID PRIMARY KEY,"movementId" UUID NOT NULL UNIQUE REFERENCES "FinanceMovement" ON DELETE RESTRICT,"partyId" UUID NOT NULL REFERENCES "FinanceParty" ON DELETE RESTRICT,"accountId" UUID NOT NULL REFERENCES "FinanceAccount" ON DELETE RESTRICT,"journalId" UUID NOT NULL UNIQUE REFERENCES "FinanceJournalEntry" ON DELETE RESTRICT,"effectiveDate" DATE NOT NULL,bucket TEXT NOT NULL CHECK(bucket IN('CAPITAL','DISTRIBUTION','FOUNDER_PAYABLE')),amount NUMERIC(20,2) NOT NULL CHECK(amount<>0));
CREATE INDEX "FinanceFundingEvent_partyId_effectiveDate_idx" ON "FinanceFundingEvent"("partyId","effectiveDate");
CREATE TRIGGER "FinanceFundingEvent_immutable" BEFORE UPDATE OR DELETE ON "FinanceFundingEvent" FOR EACH ROW EXECUTE FUNCTION encova_finance_audit_immutable();
ALTER TABLE "FinancePayableEvent" ADD COLUMN "movementId" UUID REFERENCES "FinanceMovement" ON DELETE RESTRICT;
DO $$ DECLARE def TEXT;BEGIN SELECT pg_get_constraintdef(oid) INTO def FROM pg_constraint WHERE conrelid='public."FinancePayableEvent"'::regclass AND conname='FinancePayableEvent_source_kind';ALTER TABLE "FinancePayableEvent" DROP CONSTRAINT "FinancePayableEvent_source_kind";EXECUTE 'ALTER TABLE public."FinancePayableEvent" ADD CONSTRAINT "FinancePayableEvent_source_kind" CHECK(('||substr(def,8,length(def)-8)||' AND "movementId" IS NULL) OR(kind IN(''FOUNDER_BILL_SETTLEMENT'',''FUNDING_REVERSAL'') AND amount<>0 AND "movementId" IS NOT NULL AND "supplierDocumentId" IS NULL))';END $$;
CREATE FUNCTION encova_finance_funding_expected(target UUID) RETURNS TABLE("partyId" UUID,"accountId" UUID,bucket TEXT,amount NUMERIC) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT d."partyId",d."controlAccountId",CASE WHEN d.kind IN('CAPITAL_CONTRIBUTION','CAPITAL_RETURN','NONCASH_CAPITAL') THEN 'CAPITAL' WHEN d.kind='DISTRIBUTION' THEN 'DISTRIBUTION' ELSE 'FOUNDER_PAYABLE' END,CASE WHEN d.kind IN('CAPITAL_RETURN','FOUNDER_REIMBURSEMENT') THEN -d.amount ELSE d.amount END FROM public."FinanceMovement" d WHERE d.id=target AND d.kind IN('CAPITAL_CONTRIBUTION','CAPITAL_RETURN','DISTRIBUTION','NONCASH_CAPITAL','FOUNDER_OUTLAY','FOUNDER_BILL_SETTLEMENT','FOUNDER_REIMBURSEMENT')
 UNION ALL SELECT v."partyId",v."accountId",v.bucket,-v.amount FROM public."FinanceMovement" d JOIN public."FinanceFundingEvent" v ON v."movementId"=d."reversalOfId" WHERE d.id=target AND d.kind='REVERSAL';
$$;
CREATE FUNCTION encova_finance_funding_capacity(party UUID,account UUID,bucket_name TEXT,cutoff DATE) RETURNS NUMERIC LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ SELECT coalesce(min((SELECT coalesce(sum(e.amount),0) FROM public."FinanceFundingEvent" e WHERE e."partyId"=party AND e."accountId"=account AND e.bucket=bucket_name AND e."effectiveDate"<=dates.d)),0) FROM(SELECT cutoff AS d UNION SELECT "effectiveDate" FROM public."FinanceFundingEvent" WHERE "partyId"=party AND "accountId"=account AND bucket=bucket_name AND "effectiveDate">=cutoff)dates $$;
ALTER FUNCTION encova_finance_movement_lines(UUID) RENAME TO encova_finance_movement_lines_f20;
CREATE FUNCTION encova_finance_movement_lines(target UUID) RETURNS TABLE(sequence INTEGER,"accountId" UUID,description TEXT,debit NUMERIC,credit NUMERIC,"projectId" UUID,"partyId" UUID) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT * FROM public.encova_finance_movement_lines_f20(target)
 UNION ALL SELECT 1,CASE WHEN d.kind='CAPITAL_CONTRIBUTION' THEN c."glAccountId" WHEN d.kind IN('NONCASH_CAPITAL','FOUNDER_OUTLAY','FOUNDER_BILL_SETTLEMENT') THEN d."counterAccountId" ELSE d."controlAccountId" END,d.description,d.amount,0::numeric,d."projectId",CASE WHEN d.kind='FOUNDER_BILL_SETTLEMENT' THEN b."partyId" ELSE d."partyId" END FROM public."FinanceMovement" d LEFT JOIN public."FinanceCashAccount" c ON c.id=d."toCashId" LEFT JOIN public."FinanceBill" b ON b.id=d."billId" WHERE d.id=target AND d.kind IN('CAPITAL_CONTRIBUTION','CAPITAL_RETURN','DISTRIBUTION','NONCASH_CAPITAL','FOUNDER_OUTLAY','FOUNDER_BILL_SETTLEMENT','FOUNDER_REIMBURSEMENT')
 UNION ALL SELECT 2,CASE WHEN d.kind IN('CAPITAL_CONTRIBUTION','NONCASH_CAPITAL','FOUNDER_OUTLAY','FOUNDER_BILL_SETTLEMENT') THEN d."controlAccountId" ELSE c."glAccountId" END,d.description,0::numeric,d.amount,d."projectId",d."partyId" FROM public."FinanceMovement" d LEFT JOIN public."FinanceCashAccount" c ON c.id=d."fromCashId" WHERE d.id=target AND d.kind IN('CAPITAL_CONTRIBUTION','CAPITAL_RETURN','DISTRIBUTION','NONCASH_CAPITAL','FOUNDER_OUTLAY','FOUNDER_BILL_SETTLEMENT','FOUNDER_REIMBURSEMENT');
$$;
ALTER FUNCTION encova_finance_movement_validate(UUID) RENAME TO encova_finance_movement_validate_f20;
CREATE FUNCTION encova_finance_movement_validate(target UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE d public."FinanceMovement"%ROWTYPE;a public."FinanceAccount"%ROWTYPE;b public."FinanceBill"%ROWTYPE;x RECORD;BEGIN
 SELECT * INTO d FROM public."FinanceMovement" WHERE id=target FOR UPDATE;
 IF d.id IS NULL OR d.state<>'DRAFT' THEN RAISE EXCEPTION 'FINANCE_MOVEMENT_IMMUTABLE' USING ERRCODE='P0001';END IF;
 IF d.kind IN('TRANSFER','REVERSAL') THEN PERFORM public.encova_finance_movement_validate_f20(target);ELSE
  IF NOT EXISTS(SELECT 1 FROM public."FinanceParty" WHERE id=d."partyId" AND active) OR(d."projectId" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."Project" WHERE id=d."projectId" AND "archivedAt" IS NULL)) THEN RAISE EXCEPTION 'FINANCE_MOVEMENT_MAPPING' USING ERRCODE='P0001';END IF;
  SELECT * INTO a FROM public."FinanceAccount" WHERE id=d."controlAccountId";
  IF a.id IS NULL OR NOT a.active OR NOT a."isPosting" OR a.currency<>'PKR' OR a."isContra" OR a."controlType" IS DISTINCT FROM(CASE WHEN d.kind IN('CAPITAL_CONTRIBUTION','CAPITAL_RETURN','NONCASH_CAPITAL') THEN 'CAPITAL' WHEN d.kind='DISTRIBUTION' THEN 'DISTRIBUTION' ELSE 'FOUNDER_PAYABLE' END) THEN RAISE EXCEPTION 'FINANCE_MOVEMENT_MAPPING' USING ERRCODE='P0001';END IF;
  IF d.kind IN('CAPITAL_RETURN','DISTRIBUTION','NONCASH_CAPITAL') AND(d."approvalEvidence" IS NULL OR length(trim(d."approvalEvidence")) NOT BETWEEN 3 AND 1000) THEN RAISE EXCEPTION 'FINANCE_APPROVAL_REQUIRED' USING ERRCODE='P0001';END IF;
  IF d.kind='CAPITAL_CONTRIBUTION' THEN
   IF d."toCashId" IS NULL OR d."fromCashId" IS NOT NULL OR d."counterAccountId" IS NOT NULL OR d."billId" IS NOT NULL THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  ELSIF d.kind IN('CAPITAL_RETURN','DISTRIBUTION','FOUNDER_REIMBURSEMENT') THEN
   IF d."fromCashId" IS NULL OR d."toCashId" IS NOT NULL OR d."counterAccountId" IS NOT NULL OR d."billId" IS NOT NULL THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  ELSE
   IF d."fromCashId" IS NOT NULL OR d."toCashId" IS NOT NULL OR d."counterAccountId" IS NULL THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
   SELECT * INTO a FROM public."FinanceAccount" WHERE id=d."counterAccountId";
   IF a.id IS NULL OR NOT a.active OR NOT a."isPosting" OR a."isContra" OR a.currency<>'PKR' THEN RAISE EXCEPTION 'FINANCE_MOVEMENT_MAPPING' USING ERRCODE='P0001';END IF;
   IF d.kind='NONCASH_CAPITAL' AND(a.type<>'ASSET' OR a."controlType" NOT IN('NONE','FIXED_ASSET')) OR d.kind='FOUNDER_OUTLAY' AND(a.type NOT IN('ASSET','DIRECT_COST','OPERATING_EXPENSE','OTHER_EXPENSE') OR a."controlType" NOT IN('NONE','FIXED_ASSET')) THEN RAISE EXCEPTION 'FINANCE_MOVEMENT_MAPPING' USING ERRCODE='P0001';END IF;
   IF d.kind='FOUNDER_BILL_SETTLEMENT' THEN
    SELECT * INTO b FROM public."FinanceBill" WHERE id=d."billId" FOR UPDATE;
    IF b.id IS NULL OR b.state<>'POSTED' OR b.kind<>'BILL' OR b."postingDate">d."postingDate" OR b."payableAccountId"<>a.id OR public.encova_finance_ap_capacity(b.id,d."postingDate")<d.amount THEN RAISE EXCEPTION 'FINANCE_ALLOCATION_UNAVAILABLE' USING ERRCODE='P0001';END IF;
   ELSIF d."billId" IS NOT NULL THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  END IF;
  IF coalesce(d."fromCashId",d."toCashId") IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."FinanceCashAccount" c JOIN public."FinanceAccount" a ON a.id=c."glAccountId" WHERE c.id=coalesce(d."fromCashId",d."toCashId") AND c.active AND a.active AND a.currency='PKR' AND a."isPosting" AND a."controlType"='CASH') THEN RAISE EXCEPTION 'FINANCE_MOVEMENT_MAPPING' USING ERRCODE='P0001';END IF;
 END IF;
 FOR x IN SELECT * FROM public.encova_finance_funding_expected(target) LOOP IF x.bucket<>'DISTRIBUTION' AND x.amount<0 AND public.encova_finance_funding_capacity(x."partyId",x."accountId",x.bucket,d."postingDate") < -x.amount THEN RAISE EXCEPTION 'FINANCE_FUNDING_CAPACITY' USING ERRCODE='P0001';END IF;END LOOP;
END $$;
ALTER FUNCTION encova_finance_movement_effects(UUID,UUID,UUID) RENAME TO encova_finance_movement_effects_f20;
CREATE FUNCTION encova_finance_movement_effects(actor UUID,target UUID,entry_id UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE d public."FinanceMovement"%ROWTYPE;o public."FinanceMovement"%ROWTYPE;BEGIN
 SELECT * INTO d FROM public."FinanceMovement" WHERE id=target;
 INSERT INTO public."FinanceFundingEvent"(id,"movementId","partyId","accountId","journalId","effectiveDate",bucket,amount) SELECT gen_random_uuid(),target,x."partyId",x."accountId",entry_id,d."postingDate",x.bucket,x.amount FROM public.encova_finance_funding_expected(target)x;
 IF d.kind='FOUNDER_BILL_SETTLEMENT' THEN INSERT INTO public."FinancePayableEvent"(id,"movementId","billId","partyId","accountId","journalId","effectiveDate",kind,amount) SELECT gen_random_uuid(),d.id,b.id,b."partyId",b."payableAccountId",entry_id,d."postingDate",d.kind,-d.amount FROM public."FinanceBill" b WHERE b.id=d."billId";
 ELSIF d.kind='REVERSAL' THEN INSERT INTO public."FinancePayableEvent"(id,"movementId","billId","partyId","accountId","journalId","effectiveDate",kind,amount) SELECT gen_random_uuid(),d.id,e."billId",e."partyId",e."accountId",entry_id,d."postingDate",'FUNDING_REVERSAL',-e.amount FROM public."FinancePayableEvent" e WHERE e."movementId"=d."reversalOfId";END IF;
 PERFORM public.encova_finance_movement_effects_f20(actor,target,entry_id);
END $$;
ALTER FUNCTION encova_finance_check_movement(UUID) RENAME TO encova_finance_check_movement_f20;
CREATE FUNCTION encova_finance_check_movement(target UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE d public."FinanceMovement"%ROWTYPE;e UUID;BEGIN
 IF target IS NULL THEN RETURN;END IF;PERFORM public.encova_finance_check_movement_f20(target);SELECT * INTO d FROM public."FinanceMovement" WHERE id=target;SELECT id INTO e FROM public."FinanceJournalEntry" WHERE "movementId"=target;
 IF d.state<>'POSTED' THEN IF EXISTS(SELECT 1 FROM public."FinanceFundingEvent" WHERE "movementId"=target) OR EXISTS(SELECT 1 FROM public."FinancePayableEvent" WHERE "movementId"=target) THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;RETURN;END IF;
 IF EXISTS((SELECT "partyId","accountId",bucket,amount FROM public."FinanceFundingEvent" WHERE "movementId"=target) EXCEPT(SELECT * FROM public.encova_finance_funding_expected(target))) OR EXISTS((SELECT * FROM public.encova_finance_funding_expected(target)) EXCEPT(SELECT "partyId","accountId",bucket,amount FROM public."FinanceFundingEvent" WHERE "movementId"=target)) OR EXISTS(SELECT 1 FROM public."FinanceFundingEvent" WHERE "movementId"=target AND("journalId"<>e OR "effectiveDate"<>d."postingDate")) THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;
 IF EXISTS(SELECT 1 FROM(SELECT bucket,sum(amount) OVER(PARTITION BY "partyId","accountId",bucket ORDER BY "effectiveDate" RANGE UNBOUNDED PRECEDING) balance FROM public."FinanceFundingEvent" WHERE("partyId","accountId",bucket) IN(SELECT "partyId","accountId",bucket FROM public.encova_finance_funding_expected(target)))q WHERE bucket<>'DISTRIBUTION' AND balance<0) THEN RAISE EXCEPTION 'FINANCE_FUNDING_CAPACITY' USING ERRCODE='P0001';END IF;
 IF EXISTS((SELECT "billId","partyId","accountId",amount FROM public."FinancePayableEvent" WHERE "movementId"=target) EXCEPT(SELECT b.id,b."partyId",b."payableAccountId",-d.amount FROM public."FinanceBill" b WHERE b.id=d."billId" AND d.kind='FOUNDER_BILL_SETTLEMENT' UNION ALL SELECT p."billId",p."partyId",p."accountId",-p.amount FROM public."FinancePayableEvent" p WHERE d.kind='REVERSAL' AND p."movementId"=d."reversalOfId")) OR EXISTS((SELECT b.id,b."partyId",b."payableAccountId",-d.amount FROM public."FinanceBill" b WHERE b.id=d."billId" AND d.kind='FOUNDER_BILL_SETTLEMENT' UNION ALL SELECT p."billId",p."partyId",p."accountId",-p.amount FROM public."FinancePayableEvent" p WHERE d.kind='REVERSAL' AND p."movementId"=d."reversalOfId") EXCEPT(SELECT "billId","partyId","accountId",amount FROM public."FinancePayableEvent" WHERE "movementId"=target)) OR EXISTS(SELECT 1 FROM public."FinancePayableEvent" WHERE "movementId"=target AND("journalId"<>e OR "effectiveDate"<>d."postingDate" OR kind<>CASE WHEN d.kind='REVERSAL' THEN 'FUNDING_REVERSAL' ELSE d.kind END)) THEN RAISE EXCEPTION 'FINANCE_PAYABLE_MISMATCH' USING ERRCODE='P0001';END IF;
 IF EXISTS(SELECT 1 FROM(SELECT sum(amount) OVER(PARTITION BY "billId" ORDER BY "effectiveDate" RANGE UNBOUNDED PRECEDING) balance FROM public."FinancePayableEvent" WHERE "billId" IN(SELECT "billId" FROM public."FinancePayableEvent" WHERE "movementId"=target))q WHERE balance<0) THEN RAISE EXCEPTION 'FINANCE_ALLOCATION_UNAVAILABLE' USING ERRCODE='P0001';END IF;
END $$;
CREATE FUNCTION encova_finance_funding_event_check() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN PERFORM public.encova_finance_check_movement(NEW."movementId");RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER "FinanceFundingEvent_valid" AFTER INSERT ON "FinanceFundingEvent" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION encova_finance_funding_event_check();
CREATE CONSTRAINT TRIGGER "FinancePayableEvent_funding_valid" AFTER INSERT ON "FinancePayableEvent" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION encova_finance_funding_event_check();
CREATE OR REPLACE FUNCTION encova_finance_movement_command(actor UUID,provider TEXT,session_id TEXT,verified_at TIMESTAMPTZ,action TEXT,input JSONB,request_key TEXT,request_id UUID) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE d public."FinanceMovement"%ROWTYPE;o public."FinanceMovement"%ROWTYPE;r public."FinanceLedgerReceipt"%ROWTYPE;reason TEXT;digest TEXT;operation_name TEXT;result JSONB;entry_id UUID;original_id UUID;original_version INTEGER;original_number TEXT;BEGIN
 IF action IS NULL OR action NOT IN('CREATE','UPDATE','POST','VOID','REVERSE') OR jsonb_typeof(input) IS DISTINCT FROM 'object' OR request_key IS NULL OR length(request_key) NOT BETWEEN 8 AND 128 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 IF verified_at IS NULL OR verified_at<CURRENT_TIMESTAMP-interval '5 minutes' OR verified_at>CURRENT_TIMESTAMP+interval '5 seconds' THEN RAISE EXCEPTION 'FINANCE_REAUTH_REQUIRED' USING ERRCODE='P0001';END IF;
 reason:=trim(input->>'reason');IF reason IS NULL OR length(reason) NOT BETWEEN 3 AND 500 OR input-(CASE WHEN action='CREATE' THEN ARRAY['kind','reference','documentDate','postingDate','description','evidence','approvalEvidence','currency','amount','fromCashId','toCashId','partyId','controlAccountId','counterAccountId','projectId','billId','reason'] WHEN action='UPDATE' THEN ARRAY['id','expectedVersion','kind','reference','documentDate','postingDate','description','evidence','approvalEvidence','currency','amount','fromCashId','toCashId','partyId','controlAccountId','counterAccountId','projectId','billId','reason'] WHEN action='REVERSE' THEN ARRAY['id','expectedVersion','postingDate','reason'] ELSE ARRAY['id','expectedVersion','reason'] END)<>'{}'::jsonb THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
 PERFORM pg_advisory_xact_lock(987661);PERFORM public.encova_finance_lock_person(actor);
 IF NOT EXISTS(SELECT 1 FROM public."Person" WHERE id=actor AND role='SUPER_ADMIN' AND status='ACTIVE') OR NOT public.encova_finance_session_ok(actor,provider,session_id) OR NOT EXISTS(SELECT 1 FROM public."FinanceGrant" WHERE "userId"=actor AND "revokedAt" IS NULL) THEN RAISE EXCEPTION 'FINANCE_FORBIDDEN' USING ERRCODE='P0001';END IF;
 operation_name:='MOVEMENT_'||action;digest:=encode(sha256(convert_to(jsonb_strip_nulls(input)::text,'UTF8')),'hex');SELECT * INTO r FROM public."FinanceLedgerReceipt" WHERE "actorId"=actor AND operation=operation_name AND key=request_key;
 IF FOUND THEN IF r."requestHash"<>digest THEN RAISE EXCEPTION 'FINANCE_IDEMPOTENCY_CONFLICT' USING ERRCODE='P0001';END IF;RETURN r.result;END IF;
 PERFORM pg_advisory_xact_lock(629815);
 IF action<>'CREATE' THEN
  IF jsonb_typeof(input->'expectedVersion') IS DISTINCT FROM 'number' OR(input->>'expectedVersion')::integer<1 THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  SELECT * INTO d FROM public."FinanceMovement" WHERE id=(input->>'id')::uuid FOR UPDATE;
  IF d.id IS NULL THEN RAISE EXCEPTION 'FINANCE_NOT_FOUND' USING ERRCODE='P0001';END IF;
  IF d.version<>(input->>'expectedVersion')::integer THEN RAISE EXCEPTION 'FINANCE_STALE_VERSION' USING ERRCODE='P0001';END IF;
  IF(action='REVERSE' AND d.state<>'POSTED') OR(action<>'REVERSE' AND d.state<>'DRAFT') THEN RAISE EXCEPTION 'FINANCE_MOVEMENT_IMMUTABLE' USING ERRCODE='P0001';END IF;
 END IF;
 IF action IN('CREATE','UPDATE') THEN
  IF input->>'kind' IS NULL OR input->>'kind' NOT IN('TRANSFER','CAPITAL_CONTRIBUTION','CAPITAL_RETURN','DISTRIBUTION','NONCASH_CAPITAL','FOUNDER_OUTLAY','FOUNDER_BILL_SETTLEMENT','FOUNDER_REIMBURSEMENT') OR input->>'currency' IS DISTINCT FROM 'PKR' OR jsonb_typeof(input->'amount') IS DISTINCT FROM 'string' OR input->>'amount' !~ '^(0|[1-9][0-9]{0,17})([.][0-9]{1,2})?$' OR(input->>'amount')::numeric<=0 OR input->>'documentDate' IS NULL OR input->>'documentDate' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR input->>'postingDate' IS NULL OR input->>'postingDate' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  IF input->>'kind'='TRANSFER' AND(input->>'partyId' IS NOT NULL OR input->>'controlAccountId' IS NOT NULL OR input->>'counterAccountId' IS NOT NULL OR input->>'projectId' IS NOT NULL OR input->>'approvalEvidence' IS NOT NULL OR input->>'billId' IS NOT NULL) THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;
  IF action='CREATE' THEN INSERT INTO public."FinanceMovement"(id,number,kind,reference,"documentDate","postingDate",description,evidence,"approvalEvidence",currency,amount,"fromCashId","toCashId","partyId","controlAccountId","counterAccountId","projectId","billId","createdById") VALUES(gen_random_uuid(),'MVT-'||lpad(nextval('public.finance_movement_number')::text,10,'0'),input->>'kind',input->>'reference',(input->>'documentDate')::date,(input->>'postingDate')::date,input->>'description',input->>'evidence',input->>'approvalEvidence','PKR',(input->>'amount')::numeric,(input->>'fromCashId')::uuid,(input->>'toCashId')::uuid,(input->>'partyId')::uuid,(input->>'controlAccountId')::uuid,(input->>'counterAccountId')::uuid,(input->>'projectId')::uuid,(input->>'billId')::uuid,actor) RETURNING * INTO d;
  ELSE IF input->>'kind' IS DISTINCT FROM d.kind THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';END IF;UPDATE public."FinanceMovement" SET "partyId"=(input->>'partyId')::uuid,"controlAccountId"=(input->>'controlAccountId')::uuid,"counterAccountId"=(input->>'counterAccountId')::uuid,"projectId"=(input->>'projectId')::uuid,"billId"=(input->>'billId')::uuid,"approvalEvidence"=input->>'approvalEvidence',reference=input->>'reference',"documentDate"=(input->>'documentDate')::date,"postingDate"=(input->>'postingDate')::date,description=input->>'description',evidence=input->>'evidence',amount=(input->>'amount')::numeric,"fromCashId"=(input->>'fromCashId')::uuid,"toCashId"=(input->>'toCashId')::uuid,"updatedAt"=CURRENT_TIMESTAMP,version=version+1 WHERE id=d.id RETURNING * INTO d;END IF;
 ELSIF action='VOID' THEN UPDATE public."FinanceMovement" SET state='VOIDED',version=version+1,"updatedAt"=CURRENT_TIMESTAMP WHERE id=d.id RETURNING * INTO d;
 ELSIF action='REVERSE' THEN
  IF d.kind='REVERSAL' OR input->>'postingDate' IS NULL OR input->>'postingDate' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR EXISTS(SELECT 1 FROM public."FinanceMovement" WHERE "reversalOfId"=d.id) THEN RAISE EXCEPTION 'FINANCE_REVERSAL_INVALID' USING ERRCODE='P0001';END IF;
  o:=d;original_id:=d.id;original_number:=d.number;original_version:=d.version;
  INSERT INTO public."FinanceMovement" SELECT x.* FROM jsonb_populate_record(NULL::public."FinanceMovement",to_jsonb(o)||jsonb_build_object('id',gen_random_uuid(),'number','MVT-'||lpad(nextval('public.finance_movement_number')::text,10,'0'),'kind','REVERSAL','reversalOfId',o.id,'documentDate',(input->>'postingDate')::date,'postingDate',(input->>'postingDate')::date,'state','DRAFT','version',1,'sourceSnapshot',NULL,'createdById',actor,'createdAt',CURRENT_TIMESTAMP,'updatedAt',CURRENT_TIMESTAMP,'evidence',reason)) x RETURNING * INTO d;
  entry_id:=public.encova_finance_emit_journal(actor,'MOVEMENT',d.id,d."postingDate",reason);SELECT * INTO d FROM public."FinanceMovement" WHERE id=d.id;
 ELSE entry_id:=public.encova_finance_emit_journal(actor,'MOVEMENT',d.id,d."postingDate",reason);SELECT * INTO d FROM public."FinanceMovement" WHERE id=d.id;END IF;
 result:=CASE WHEN action='REVERSE' THEN jsonb_build_object('id',original_id,'version',original_version,'number',original_number,'journalId',entry_id,'reversalId',d.id) ELSE jsonb_build_object('id',d.id,'version',d.version,'number',d.number,'journalId',entry_id) END;
 INSERT INTO public."FinanceLedgerReceipt"(id,"actorId",operation,key,"requestHash",result) VALUES(gen_random_uuid(),actor,operation_name,request_key,digest,result);
 INSERT INTO public."FinanceAuditEvent"(id,"actorId",action,"entityType","entityId",reason,data,"requestId") VALUES(gen_random_uuid(),actor,'FINANCE_'||operation_name,'FinanceMovement',coalesce(original_id,d.id),reason,jsonb_build_object('journalId',entry_id,'snapshot',to_jsonb(d)||jsonb_build_object('amount',d.amount::text)),request_id);RETURN result;
EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'FINANCE_DUPLICATE' USING ERRCODE='P0001';
 WHEN check_violation OR not_null_violation OR foreign_key_violation OR invalid_datetime_format OR datetime_field_overflow OR invalid_text_representation OR numeric_value_out_of_range THEN RAISE EXCEPTION 'FINANCE_INVALID_INPUT' USING ERRCODE='P0001';
END $$;
DO $$ DECLARE f RECORD;role_name TEXT;BEGIN
 ALTER TABLE "FinanceFundingEvent" ENABLE ROW LEVEL SECURITY;REVOKE ALL ON "FinanceFundingEvent" FROM PUBLIC;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='encova_app') THEN GRANT SELECT ON "FinanceFundingEvent" TO encova_app;CREATE POLICY encova_server_read ON "FinanceFundingEvent" FOR SELECT TO encova_app USING(true);END IF;
 FOR f IN SELECT oid::regprocedure AS signature FROM pg_proc WHERE pronamespace='public'::regnamespace AND(proname LIKE 'encova_finance_funding_%' OR proname LIKE 'encova_finance_movement_%' OR proname LIKE 'encova_finance_check_movement%') LOOP
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);
 FOREACH role_name IN ARRAY ARRAY['anon','authenticated','encova_app'] LOOP IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname=role_name) THEN EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',f.signature,role_name);END IF;END LOOP;END LOOP;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname='encova_app') THEN GRANT EXECUTE ON FUNCTION encova_finance_movement_command(UUID,TEXT,TEXT,TIMESTAMPTZ,TEXT,JSONB,TEXT,UUID) TO encova_app;END IF;
 END $$;
COMMIT;
